PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE SITE( ASSET_ID INTEGER PRIMARY KEY, SITE_NM TEXT, SITE_CD TEXT, REGION_CD TEXT, LAT REAL, LON REAL, STATUS_CD INTEGER, TOWER_REG TEXT, TOTAL_CAP_MBPS INTEGER, ALLOC_CAP_MBPS INTEGER);
CREATE TABLE CIRCUIT( CIRCUIT_ID TEXT PRIMARY KEY, CIRCUIT_NM TEXT, A_ASSET_ID INTEGER, Z_ASSET_ID INTEGER, CAP_MBPS INTEGER, ALLOC_MBPS INTEGER, ROLE_CD INTEGER, STATUS_CD INTEGER);
COMMIT;
